"use client";

import { Player } from "@remotion/player";
import { DynamicComposition, DEFAULT_SEQUENCES } from "../src/Composition";
import type { CompositionDTO } from "../src/types";

interface VideoPlayerProps {
  /** Composición cargada desde Firestore. Si no se pasa, usa la composición por defecto. */
  composition?: CompositionDTO;
}

export default function VideoPlayer({ composition }: VideoPlayerProps) {
  const fps = composition?.fps ?? 30;
  const width = composition?.width ?? 1920;
  const height = composition?.height ?? 1080;
  const sequences = composition?.sequences ?? DEFAULT_SEQUENCES;
  const totalDuration =
    composition?.totalDurationInFrames ??
    // 910 frames − 125 de transiciones = 785
    785;

  return (
    <div
      style={{
        width: "100%",
        maxWidth: 960,
        borderRadius: 12,
        overflow: "hidden",
        boxShadow:
          "0 0 0 1px rgba(157,255,32,0.15), 0 24px 80px rgba(0,0,0,0.6)",
      }}
    >
      <Player
        component={DynamicComposition}
        inputProps={{ sequences }}
        durationInFrames={totalDuration}
        fps={fps}
        compositionWidth={width}
        compositionHeight={height}
        style={{ width: "100%" }}
        controls
        loop
        autoPlay={false}
        clickToPlay
        acknowledgeRemotionLicense
      />
    </div>
  );
}
